<script setup lang="ts">
import { ref, onMounted } from 'vue'
import gsap from 'gsap'

const sectionRef = ref<HTMLElement | null>(null)
const mapRef = ref<HTMLElement | null>(null)
const signalsRef = ref<HTMLElement[]>([])

const setSignalRef = (el: any) => {
  if (el && !signalsRef.value.includes(el)) {
    signalsRef.value = [...signalsRef.value, el]
  }
}

onMounted(() => {
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
  if (reduced) return

  // Flottement doux de la carte
  if (mapRef.value) {
    gsap.to(mapRef.value, {
      y: -8,
      duration: 5,
      repeat: -1,
      yoyo: true,
      ease: 'sine.inOut',
    })
  }

  // Pulsation radar + bulles des points de signal
  signalsRef.value.forEach((signal, index) => {
    const ring = signal.querySelector('[data-ring]')
    const bubble = signal.querySelector('[data-bubble]')

    if (ring) {
      gsap.fromTo(
        ring,
        { scale: 0.8, opacity: 0.9 },
        {
          scale: 2.4,
          opacity: 0,
          duration: 2.2,
          repeat: -1,
          delay: index * 0.5,
          ease: 'power2.out',
        }
      )
    }

    if (bubble) {
      gsap.to(bubble, {
        y: -14,
        x: (index % 2 === 0 ? 10 : -10),
        opacity: 1,
        duration: 1.6,
        repeat: -1,
        yoyo: true,
        delay: index * 0.3,
        ease: 'sine.inOut',
      })
    }
  })
})
</script>

